const LAB_ITEMS=[{"id":"cpu","name":"CPU (processor)","kind":"component","short":"CPU","color":"#ffbf3f","hint":"Find the large square socket in the upper-middle of the board.","definition":"The central processing unit executes instructions and performs calculations.","description":"Align the corner marker, lower the CPU into the matching socket, and secure it. Never force it.","specs":["Socket must match the motherboard","Core and thread count","Clock speed measured in GHz","Thermal design power (TDP)"]},{"id":"cooler","name":"CPU cooler","kind":"component","short":"FAN","color":"#8ecae6","hint":"It mounts directly over the installed processor.","definition":"A heatsink and fan assembly that removes heat from the CPU.","description":"Apply thermal compound, secure the cooler evenly, then connect its fan lead.","specs":["Must support the CPU socket","Air or liquid cooling","Commonly uses 4-pin PWM","Cooling capacity should meet CPU TDP"],"requires":"cpu"},{"id":"ram","name":"DDR memory (RAM)","kind":"component","short":"RAM","color":"#90be6d","hint":"Find the long paired slots next to the CPU socket.","definition":"Random-access memory temporarily stores active programs and data.","description":"Match the module notch to the DIMM slot and press until the clips lock.","specs":["DDR generation must match","Desktop DIMM form factor","Capacity measured in GB","Speed listed in MT/s"]},{"id":"gpu","name":"Graphics card (GPU)","kind":"component","short":"GPU","color":"#f28482","hint":"Use the longest expansion slot, normally closest to the CPU.","definition":"A graphics processor renders images, video, and accelerated workloads.","description":"Install it in the primary PCIe x16 slot and secure its rear bracket.","specs":["PCIe x16 interface","VRAM capacity","Display outputs","PSU wattage and connectors"]},{"id":"m2","name":"M.2 NVMe SSD","kind":"component","short":"M.2","color":"#cdb4db","hint":"Look for the short horizontal socket between expansion areas.","definition":"A compact solid-state drive using PCI Express and NVMe.","description":"Insert at a slight angle, lower it, and secure it with the latch or standoff.","specs":["Common size: 2280","PCIe/NVMe interface","Key type must match","No separate cables"]},{"id":"atx","name":"24-pin ATX power cable","kind":"cable","short":"24","color":"#f6bd60","hint":"Find the large two-row socket on the right edge.","definition":"The main power connection from the PSU to the motherboard.","description":"The keyed plug powers the board, memory, slots, chipset, and onboard devices.","specs":["24 pins","Keyed connector","Locking clip","Multiple voltage rails"]},{"id":"eps","name":"8-pin CPU/EPS cable","kind":"cable","short":"8","color":"#84a59d","hint":"Look near the top-left corner, close to the CPU.","definition":"A dedicated 12-volt power cable for the CPU voltage regulators.","description":"Connect it near the CPU. EPS and PCIe plugs are not interchangeable.","specs":["Usually 4+4-pin","12-volt CPU power","Keyed pin shapes","Top-edge location"]},{"id":"cpufan","name":"CPU fan cable","kind":"cable","short":"PWM","color":"#74c0fc","hint":"Find the small header above or beside the CPU socket.","definition":"A lead that lets the motherboard power and control the CPU fan.","description":"Connect it to CPU_FAN so firmware can monitor speed and protect the system.","specs":["Usually 4-pin PWM","3-pin may fit","Reports RPM","Firmware-controlled"],"requires":"cooler"},{"id":"sata","name":"SATA data cable","kind":"cable","short":"SATA","color":"#00b4d8","hint":"Find the grouped right-facing ports on the board edge.","definition":"A seven-pin data cable connecting a SATA drive to the motherboard.","description":"It carries data only; the drive also needs SATA power from the PSU.","specs":["7 pins","SATA III up to 6 Gb/s","L-shaped key","One drive per cable"]},{"id":"usb3","name":"Front USB 3.x cable","kind":"cable","short":"USB","color":"#4cc9f0","hint":"Find the wide pin header near the right edge.","definition":"A case cable linking front USB ports to an internal motherboard header.","description":"Align the wide keyed plug carefully to avoid bending header pins.","specs":["19/20-position header","Keyed missing pin","Front USB-A ports","Not USB 2.0"]},{"id":"audio","name":"HD Audio cable","kind":"cable","short":"AUDIO","color":"#b8c0ff","hint":"Look along the lower-left edge near onboard audio.","definition":"A case cable connecting front headphone and microphone jacks.","description":"Connect it to the keyed audio header along the lower-left edge.","specs":["10-position block","One missing pin","Headphone and microphone","Marked HD AUDIO"]},{"id":"front","name":"Front-panel switch/LED leads","kind":"cable","short":"PANEL","color":"#ff99c8","hint":"Find the small pin group at the lower-right corner.","definition":"Case leads for power, reset, power LED, and drive LED.","description":"Match each lead to the correct pins. LED polarity matters; switch polarity does not.","specs":["Power/reset switches","Power/drive LEDs","LED polarity","Layout varies"]}];
const LAB_ZONES=["eps","cpufan","cpu","cooler","ram","atx","usb3","m2","gpu","sata","audio","front"];
let labPlaced={},labSelected=null,labAttempts=0,labMistakes=0,labKind="all";
function labItem(id){return LAB_ITEMS.find(function(x){return x.id===id})}
function renderLab(){var remain=LAB_ITEMS.filter(function(x){return !labPlaced[x.id]&&(labKind==="all"||x.kind===labKind)});$("#labParts").innerHTML=remain.map(function(x){return '<button class="labPart '+(labSelected===x.id?"selected":"")+'" draggable="true" data-id="'+x.id+'"><i class="'+x.kind+'" style="background:'+x.color+'">'+x.short+'</i><span><b>'+x.name+'</b><small>'+x.kind+'</small></span></button>'}).join("")||'<p class="labDone">This group is complete ✓</p>';document.querySelectorAll(".labPart").forEach(function(b){b.onclick=function(){selectLab(b.dataset.id)};b.ondragstart=function(e){e.dataTransfer.setData("text/plain",b.dataset.id);selectLab(b.dataset.id)}});$("#labInstalled").textContent=Object.keys(labPlaced).length+"/"+LAB_ITEMS.length;$("#labAttempts").textContent=labAttempts;$("#labMistakes").textContent=labMistakes;$("#labAccuracy").textContent=(labAttempts?Math.round(Object.keys(labPlaced).length/labAttempts*100):100)+"%"}
function buildBoard(){LAB_ZONES.forEach(function(id){var b=document.createElement("button");b.className="labZone "+id;b.dataset.id=id;b.setAttribute("aria-label","Unlabeled motherboard connection point");b.innerHTML="<span></span>";b.onclick=function(){placeLab(id)};b.ondragover=function(e){e.preventDefault()};b.ondrop=function(e){e.preventDefault();placeLab(id,e.dataTransfer.getData("text/plain"))};$("#trainingBoard").appendChild(b)})}
function selectLab(id){labSelected=id;$("#labHint").textContent=labItem(id).hint;$("#labMessage").textContent=labItem(id).name+" selected. Find its unlabeled connection.";renderLab()}
function placeLab(zoneId,dragged){var id=dragged||labSelected;if(!id||labPlaced[zoneId])return;var item=labItem(id);labAttempts++;if(item.requires&&!labPlaced[item.requires]){labMistakes++;$("#labMessage").textContent="Install the "+labItem(item.requires).name+" first.";renderLab();return}if(id!==zoneId){labMistakes++;$("#labMessage").textContent="Incorrect. That location does not accept "+item.name+".";renderLab();return}labPlaced[id]=true;labSelected=null;var zone=document.querySelector('.labZone[data-id="'+id+'"]');zone.classList.add("filled");zone.innerHTML='<i style="background:'+item.color+'">'+item.short+'</i><b>'+item.name+'</b><em>✓</em>';if(id==="cpu")document.querySelector(".labZone.cooler").classList.add("available");$("#labMessage").textContent="Correct. Review the definition and specifications for "+item.name+".";$("#labLesson").className="labLesson";$("#labLesson").innerHTML='<div class="lessonTitle"><i style="background:'+item.color+'">'+item.short+'</i><div><span>CORRECT INSTALLATION</span><h3>'+item.name+'</h3></div></div><div class="lessonGrid"><article><b>Definition</b><p>'+item.definition+'</p></article><article><b>How it connects</b><p>'+item.description+'</p></article><article><b>Key specifications</b><ul>'+item.specs.map(function(s){return "<li>"+s+"</li>"}).join("")+'</ul></article></div>';renderLab()}
document.querySelectorAll(".labFilter").forEach(function(b){b.onclick=function(){document.querySelectorAll(".labFilter").forEach(function(x){x.classList.remove("active")});b.classList.add("active");labKind=b.dataset.kind;renderLab()}});
$("#resetLab").onclick=function(){labPlaced={};labSelected=null;labAttempts=0;labMistakes=0;$("#trainingBoard").querySelectorAll(".labZone").forEach(function(z){z.remove()});buildBoard();$("#labMessage").textContent="Choose a part, then identify its unlabeled location.";$("#labHint").textContent="Select an item to begin.";$("#labLesson").className="labLesson locked";$("#labLesson").innerHTML="<h3>Learning card locked</h3><p>Correctly place an item to reveal its definition, connection details, and specifications.</p>";renderLab()};
buildBoard();renderLab();

