let activePractical="assembly",scenarioIndex=0,scenarioAnswered=false,scenarioCompleted={};
function initLabCenter(){var s=$("#labModuleSelect");s.innerHTML=PRACTICAL_LABS.map(function(l){return '<option value="'+l.id+'">'+l.title+'</option>'}).join("");s.onchange=function(){openPractical(s.value)};openPractical("assembly")}
function openPractical(id){activePractical=id;scenarioIndex=0;scenarioAnswered=false;var isAssembly=id==="assembly";$("#assemblyLabPane").classList.toggle("hidden",!isAssembly);$("#scenarioLabPane").classList.toggle("hidden",isAssembly);if(!isAssembly)renderScenario()}
function renderScenario(){var lab=PRACTICAL_LABS.find(function(l){return l.id===activePractical}),step=lab.steps[scenarioIndex];$("#scenarioDomain").textContent=lab.domain;$("#scenarioTitle").textContent=lab.title;$("#scenarioIntro").textContent=lab.intro;$("#scenarioStep").textContent=Math.min(scenarioIndex+1,lab.steps.length)+"/"+lab.steps.length;$("#scenarioChecklist").innerHTML=lab.steps.map(function(x,i){return '<div class="checkStep '+(i<scenarioIndex?"done":i===scenarioIndex?"current":"")+'"><i>'+(i<scenarioIndex?"✓":i+1)+'</i><span>Step '+(i+1)+'</span></div>'}).join("");$("#scenarioComplete").classList.add("hidden");$("#scenarioTag").textContent="STEP "+(scenarioIndex+1);$("#scenarioPrompt").textContent=step.p;$("#scenarioChoices").innerHTML=step.c.map(function(c,i){return '<button data-choice="'+i+'">'+c+'</button>'}).join("");$("#scenarioFeedback").textContent="";$("#nextScenario").classList.add("hidden");scenarioAnswered=false;document.querySelectorAll("#scenarioChoices button").forEach(function(b){b.onclick=function(){answerScenario(Number(b.dataset.choice))}})}
function answerScenario(choice){if(scenarioAnswered)return;var lab=PRACTICAL_LABS.find(function(l){return l.id===activePractical}),step=lab.steps[scenarioIndex];scenarioAnswered=true;document.querySelectorAll("#scenarioChoices button").forEach(function(b){var n=Number(b.dataset.choice);if(n===step.a)b.classList.add("correct");else if(n===choice)b.classList.add("wrong")});if(choice===step.a){$("#scenarioFeedback").innerHTML="<b>Correct.</b> "+step.e}else{$("#scenarioFeedback").innerHTML="<b>Review:</b> "+step.e}$("#nextScenario").textContent=scenarioIndex===lab.steps.length-1?"Complete lab":"Next step";$("#nextScenario").classList.remove("hidden")}
$("#nextScenario").onclick=function(){var lab=PRACTICAL_LABS.find(function(l){return l.id===activePractical});if(scenarioIndex<lab.steps.length-1){scenarioIndex++;renderScenario()}else{scenarioCompleted[activePractical]=true;localStorage.setItem("aplusLabProgress",JSON.stringify(scenarioCompleted));$("#scenarioComplete").classList.remove("hidden");$("#scenarioComplete").innerHTML='<b>Lab complete: '+lab.title+'</b><p>You completed all '+lab.steps.length+' technician decisions. Restart the lab to practice the procedure again.</p>';$("#nextScenario").classList.add("hidden")}};
$("#restartScenario").onclick=function(){scenarioIndex=0;renderScenario()};
try{scenarioCompleted=JSON.parse(localStorage.getItem("aplusLabProgress")||"{}")}catch(e){scenarioCompleted={}}
initLabCenter();

