function normalizeRecallText(text){
 return String(text).toLowerCase().replace(/[’']/g,"").replace(/[-/]/g," ").replace(/[^a-z0-9 .;]/g," ").replace(/\s+/g," ").trim();
}
function gradeRecallAnswer(card,answer){
 const text=normalizeRecallText(answer);
 if(!text || /^(i )?(dont know|do not know|not sure|idk|no idea)[.! ]*$/.test(text))return {empty:true};
 const rubric=RECALL_RUBRICS[card.module+"|"+card.q];
 if(!rubric)return {unavailable:true};
 const exact=normalizeRecallText(card.a)===text;
 const port=/What port does/.test(card.q);
 const numbers=text.match(/\b\d+\b/g)||[];
 const results=rubric.map(([idea,pattern])=>({idea,matched:exact||(port?numbers.length===1&&numbers[0]===pattern:new RegExp("\\b(?:"+pattern+")","i").test(text))}));
 const matched=results.filter(x=>x.matched);
 const score=Math.round(100*matched.length/results.length);
 // Flag negation/uncertainty instead of pretending keyword coverage establishes truth.
 const review=!exact && /\b(no|not|never|dont|doesnt|cannot|cant|isnt|arent|without|maybe|unsure|probably)\b/.test(text);
 return {score,review,matched:matched.map(x=>x.idea),missing:results.filter(x=>!x.matched).map(x=>x.idea)};
}
function resetRecallGrade(){
 const panel=$("#recallGrade");if(panel){panel.textContent="";panel.classList.add("hidden")}
 const button=$("#checkRecall");if(button){button.textContent="Check my answer";button.disabled=false;button.classList.remove("hidden")}
}
function checkRecallAnswer(){
 if(!recallCard)return;
 const panel=$("#recallGrade"),result=gradeRecallAnswer(recallCard,$("#recallAnswer").value);
 panel.classList.remove("hidden");
 if(result.empty){panel.textContent="Write your explanation first, or use Reveal key answer to review.";return}
 if(result.unavailable){panel.textContent="This card does not yet have a concept rubric. Reveal the key answer and compare your explanation.";return}
 const verdict=result.review?"Review wording":result.score>=80?"Strong key-idea coverage":result.score>=40?"Partly there":"Review the main idea";
 const list=(label,items)=>items.length?"<h4>"+label+"</h4><ul>"+items.map(x=>"<li>"+studyEscape(x)+"</li>").join("")+"</ul>":"";
 panel.innerHTML="<h3>"+verdict+"</h3><p><b>"+result.score+"% key-idea coverage</b> — "+result.matched.length+" of "+(result.matched.length+result.missing.length)+" checks matched.</p>"+
 list("Ideas recognized",result.matched)+list("Not recognized — check or add these",result.missing)+
 (result.review?"<p><b>Wording check:</b> Your answer includes negation or uncertainty. Compare what you said with the key: shared terms can still express opposite meanings.</p>":"")+
 "<p><small>Estimated concept coverage, not a guaranteed correctness grade. This lightweight checker recognizes selected phrases and synonyms, but can miss valid paraphrases or contradictions. Missing means not recognized, not necessarily wrong.</small></p>"+
 "<p>Compare the key below. You can revise and check again; choose Again, Hard, Good, or Easy yourself. Checking does not change your progress.</p>";
 $("#recallKey").classList.remove("hidden");$("#revealRecall").classList.add("hidden");
 $("#checkRecall").textContent="Check revised answer";
}

$("#recallAnswer").maxLength=4000;
$("#recallAnswer").setAttribute("aria-label","Your explanation from memory");
$("#revealRecall").insertAdjacentHTML("beforebegin",'<button id="checkRecall" class="primary" type="button">Check my answer</button><p><small>Explain it in your own words. Checks key ideas and selected synonyms, not verbatim wording. Up to 4,000 characters.</small></p><div id="recallGrade" class="recallKey hidden" role="status" aria-live="polite"></div>');
$("#checkRecall").onclick=checkRecallAnswer;
$("#recallAnswer").addEventListener("input",resetRecallGrade);
